declare
  r record;
begin
  for r in
    select u.id
    from public.inventory_units u
    where u.installation_id = p_installation_id
      and u.status = 'assigned'
  loop
    insert into public.inventory_unit_events (unit_id, to_status, reason)
    values (r.id, 'in_stock', p_reason);
  end loop;
end;
